namespace BuildingBlocks.Notifications;

/// <summary>
/// Shared LegalSynq branding for transactional email. The logo is delivered as
/// an inline MIME attachment so it does not depend on tenant DNS or remote-image
/// downloads at the time the message is opened.
/// </summary>
public static class LegalSynqEmailBranding
{
    public const string LogoContentId = "legalsynq-logo";
    public const string LogoSource = "cid:" + LogoContentId;
    public const string LogoFileName = "legalsynq-logo.png";
    public const string LogoMediaType = "image/png";

    public static object[] CreateInlineLogoAttachment() =>
    [
        new
        {
            content = LogoBase64,
            filename = LogoFileName,
            type = LogoMediaType,
            disposition = "inline",
            contentId = LogoContentId,
        },
    ];

    // apps/web/public/legalsynq-logo.png (407 x 116)
    private const string LogoBase64 =
        "";
}
